//! Independent frozen print_ast errors for accepted GraphQL literals. The
//! expected messages and locations are generated by graphql-core, not Rust.
use catabolic_store::{Store, graphql, migration};
use serde_json::{Value, json};

#[test]
fn frozen_literal_diagnostics_keep_lexemes_escapes_and_block_node_kind() {
    let root = tempfile::tempdir().unwrap();
    let path = root.path().join("literal-diagnostics.db");
    migration::initialize(&path).unwrap();
    let mut store = Store::open(&path, true, false).unwrap();
    let fixtures: Value = serde_json::from_str(include_str!(
        "../../../tests/parity/graphql-literal-diagnostics.json"
    ))
    .unwrap();
    let mut failures = vec![];
    for case in fixtures["cases"].as_array().unwrap() {
        let (returned, report) = graphql::execute_store(
            store,
            case["document"].as_str().unwrap(),
            "default",
            json!({}),
            None,
            5000,
        )
        .unwrap();
        store = returned;
        if report != case["expected"] {
            failures.push(format!(
                "{}: expected {}, got {}",
                case["name"], case["expected"], report
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn lexical_diagnostics_do_not_change_accepted_integer_and_string_values() {
    let root = tempfile::tempdir().unwrap();
    let path = root.path().join("accepted-literals.db");
    migration::initialize(&path).unwrap();
    let mut store = Store::open(&path, true, false).unwrap();
    store
        .db
        .execute(
            "INSERT INTO items(id,kind,metadata) VALUES('0','movie','{}')",
            [],
        )
        .unwrap();
    for document in [
        "{item(id:-0){id}}",
        "query($id:ID=-0){item(id:$id){id}}",
        "{item(id:\"\"\"0\"\"\"){id}}",
        "query($id:ID=\"\"\"0\"\"\"){item(id:$id){id}}",
        "{item(id:\"\\u0030\"){id}}",
    ] {
        let (returned, report) =
            graphql::execute_store(store, document, "default", json!({}), None, 5000).unwrap();
        store = returned;
        assert!(report.get("errors").is_none(), "{document}: {report}");
        assert_eq!(report["data"]["item"]["id"], "0");
    }
}
